(window.CRAM_PERSONAL=window.CRAM_PERSONAL||{})["physical-diagnosis-2-exam-2"]={"title":"Physical Diagnosis 2 Exam 2","sections":[{"id":"l5-emphasis","title":"★ What the lecture kept coming back to","style":"--acc:#b8860b;--acc-bg:#f5eedd;--acc-zebra:#faf7ee;--acc-ink:#906909"},{"id":"l5-history","title":"The Cardiac History","style":"--acc:#3a5a40;--acc-bg:#e3e8e4;--acc-zebra:#f1f3f2;--acc-ink:#2d4632"},{"id":"l5-cycle","title":"Cardiac Cycle & Heart Sounds","style":"--acc:#46704f;--acc-bg:#e5ebe6;--acc-zebra:#f2f5f3;--acc-ink:#37573e"},{"id":"l5-impulse","title":"Apical Impulse & Point of Maximal Impulse","style":"--acc:#5f8a68;--acc-bg:#e9efea;--acc-zebra:#f4f7f4;--acc-ink:#4a6c51"},{"id":"l5-auscultation","title":"Auscultation — Areas, Diaphragm & Bell","style":"--acc:#2f6b5e;--acc-bg:#e2eae8;--acc-zebra:#f0f5f4;--acc-ink:#255349"},{"id":"l5-murmur-describe","title":"Describing & Grading Murmurs","style":"--acc:#c08a2e;--acc-bg:#f6efe2;--acc-zebra:#fbf7f0;--acc-ink:#966c24"},{"id":"l5-murmurs","title":"The Murmurs One by One","style":"--acc:#7a3b3b;--acc-bg:#ece4e4;--acc-zebra:#f6f1f1;--acc-ink:#5f2e2e"},{"id":"l5-maneuvers","title":"Maneuvers","style":"--acc:#5b4a8a;--acc-bg:#e8e6ef;--acc-zebra:#f4f2f7;--acc-ink:#473a6c"},{"id":"l5-peripheral","title":"Peripheral Vascular Examination","style":"--acc:#8a5a2b;--acc-bg:#efe8e1;--acc-zebra:#f7f3f0;--acc-ink:#6c4622"},{"id":"l5-edema","title":"Peripheral Edema","style":"--acc:#3f5b6b;--acc-bg:#e4e8ea;--acc-zebra:#f2f4f5;--acc-ink:#314753"},{"id":"l5-exam","title":"Running the Examination","style":"--acc:#4a4a4a;--acc-bg:#e6e6e6;--acc-zebra:#f2f2f2;--acc-ink:#3a3a3a"},{"id":"l6-emphasis","title":"★ Thorax & Lungs: what the lecture kept coming back to","style":"--acc:#b8860b;--acc-bg:#f5eedd;--acc-zebra:#faf7ee;--acc-ink:#906909"},{"id":"l6-landmarks","title":"Thorax Landmarks & Procedures","style":"--acc:#3a5a40;--acc-bg:#e3e8e4;--acc-zebra:#f1f3f2;--acc-ink:#2d4632"},{"id":"l6-history","title":"The Respiratory History","style":"--acc:#46704f;--acc-bg:#e5ebe6;--acc-zebra:#f2f5f3;--acc-ink:#37573e"},{"id":"l6-clubbing","title":"Clubbing & Hemoptysis","style":"--acc:#7a3b3b;--acc-bg:#ece4e4;--acc-zebra:#f6f1f1;--acc-ink:#5f2e2e"},{"id":"l6-dyspnea","title":"Dyspnea: Sudden vs Gradual vs Episodic","style":"--acc:#2f6b5e;--acc-bg:#e2eae8;--acc-zebra:#f0f5f4;--acc-ink:#255349"},{"id":"l6-inspect","title":"Survey, Inspection & Palpation","style":"--acc:#5f8a68;--acc-bg:#e9efea;--acc-zebra:#f4f7f4;--acc-ink:#4a6c51"},{"id":"l6-sounds","title":"Percussion & Breath Sounds","style":"--acc:#c08a2e;--acc-bg:#f6efe2;--acc-zebra:#fbf7f0;--acc-ink:#966c24"},{"id":"l6-adventitious","title":"Adventitious Sounds","style":"--acc:#5b4a8a;--acc-bg:#e8e6ef;--acc-zebra:#f4f2f7;--acc-ink:#473a6c"},{"id":"l6-five","title":"The Five Conditions & Voice Sounds","style":"--acc:#3f5b6b;--acc-bg:#e4e8ea;--acc-zebra:#f2f4f5;--acc-ink:#314753"}],"rows":[{"t":"★ The sound is not the diagnosis","d":"Document what you hear, when and where: 'grade 4/6 systolic ejection murmur, crescendo-decrescendo, loudest at the right 2nd intercostal space, radiating to the carotids, with a thrill.' The disease name (aortic stenosis) goes in the differential, not the physical examination.","s":0},{"t":"★ Try before you buy","d":"Tricuspid is the FIRST valve blood crosses on its way back to the heart (tricuspid before bicuspid/mitral). Said twice: 'That is important, that is important.'","s":0},{"t":"★ Hypertrophic obstructive cardiomyopathy","d":"Learn this murmur so you do not sign off a sports physical wrongly. Aortic and pulmonic stenosis worry you at a point; this one worries you, period. Murmur LOUDER with Valsalva or standing = echocardiogram, no activity until done.","s":0},{"t":"★ Mitral vs tricuspid regurgitation","d":"Both pansystolic. Mitral (apex) radiates to the LEFT AXILLA; tricuspid (lower left sternal border) does NOT. Loudest spot plus the axilla decides it.","s":0},{"t":"★ The thrill is the jump","d":"Loudness raises the grade, but a palpable thrill makes it at least grade 4/6. An arteriovenous fistula is what a thrill feels like.","s":0},{"t":"★ Weight before swelling","d":"Up to 10% of body weight can accumulate before pitting shows. Two pounds overnight is water. Daily morning weight; know a dialysis or heart failure patient's dry weight.","s":0},{"t":"★ Syncope: before and after","d":"Prodrome (lightheaded, pale, clammy) = vasovagal. On standing = orthostatic. Sudden, no warning = think arrhythmia (no wake-up or no pulse: defibrillator, 911). Confused afterward = postictal, think seizure. Feel faint? Sit down.","s":0},{"t":"★ Negative Homans does not reassure","d":"Do it when you already suspect deep vein thrombosis, on the worrying leg. Positive confirms suspicion; negative in a high-risk story, still worried.","s":0},{"t":"Time on topic","d":"No exam-scope statements in 138 minutes. Cardiac content took about 110 minutes; peripheral vascular about 25 ('almost entirely review... the cardiac stuff is a lot of new').","s":0},{"t":"Symptoms to ask","d":"Chest pain, palpitations, dyspnea, orthopnea, paroxysmal nocturnal dyspnea, edema, syncope. Quantify the baseline level of activity.","s":1},{"t":"Chest pain","d":"Most common symptom of coronary artery disease. Always consider angina, myocardial infarction, dissecting aortic aneurysm, pulmonary embolism. Open-ended first, then details; ask the patient to point.","s":1},{"t":"Atypical presentation","d":"Women over 65: upper back, neck or jaw pain, shortness of breath, paroxysmal nocturnal dyspnea, nausea, vomiting, fatigue.","s":1},{"t":"Palpitations","d":"Unpleasant awareness of the heartbeat (skipping, racing, fluttering, pounding). Anxiety and hyperthyroidism cause them; not necessarily heart disease. Get an electrocardiogram.","s":1},{"t":"Dyspnea","d":"Uncomfortable awareness of breathing inappropriate to the level of exertion. Cardiac or pulmonary.","s":1},{"t":"Orthopnea","d":"Dyspnea supine, better sitting up. Count the pillows, and ask what they are for.","s":1},{"t":"Paroxysmal nocturnal dyspnea","d":"Sudden dyspnea waking the patient, usually 1-2 hours after going to bed; sits up or goes to the window. May wheeze and cough.","s":1},{"t":"Syncope","d":"Transient loss of consciousness with recovery. Most common: neurocardiogenic (vasovagal). Arrhythmia in about 20%.","s":1},{"t":"Systole vs diastole","d":"Named for the VENTRICLES. Systole: contraction, S1 to S2. Diastole: relaxation and filling, S2 to S1.","s":2},{"t":"S1 (lub)","d":"Mitral + tricuspid closure. Diaphragm, apex. Usually not split. Precedes the carotid pulse.","s":2},{"t":"S2 (dub)","d":"Aortic (A2, usually louder) + pulmonic (P2) closure. Diaphragm, base. Follows the carotid pulse.","s":2},{"t":"Physiologic splitting","d":"S2 split on INSPIRATION, fused on expiration. Normal. Best at the pulmonic area.","s":2},{"t":"Pathologic splitting","d":"Audible split on EXPIRATION: suggests heart disease. Tends to be fixed.","s":2},{"t":"Early ejection sound","d":"Just after S1; high, clicking; diaphragm. Aortic: base and apex, no change with inspiration. Pulmonic: 2nd-3rd intercostal spaces, decreases with inspiration.","s":2},{"t":"Click","d":"Mid to late systolic, at or medial to the apex; high, diaphragm. Mitral valve prolapse; followed by a late systolic murmur crescendoing to S2.","s":2},{"t":"S3 ventricular gallop","d":"After S2: Ken-TUC-ky. Bell, apex, left lateral decubitus. Normal to about 35-40 and in late pregnancy; over 40 = heart failure, volume overload.","s":2},{"t":"S4 atrial gallop","d":"Before S1: Ten-nes-SEE. Dull, low; bell, apex, left lateral decubitus. Stiff ventricle: hypertension, aortic stenosis. Normal in athletes and older adults. Right-sided S4 at lower left sternal border, louder with inspiration.","s":2},{"t":"Opening snap","d":"Very early diastole, stenotic MITRAL valve. HIGH pitch, diaphragm. Can be mistaken for P2. Fades as the leaflets calcify.","s":2},{"t":"Normal","d":"5th intercostal space at or just medial to the left midclavicular line. Marks the LEFT border of the heart. About 2.5 cm (a quarter) supine, brisk and tapping. Judge larger than normal, not by a fixed number.","s":3},{"t":"Displaced","d":"Enlarged heart: lateral and possibly inferior (for example 6th space, anterior axillary line). Document where you find it.","s":3},{"t":"Can't find it","d":"Left lateral decubitus; then exhale fully and hold.","s":3},{"t":"Hyperkinetic","d":"Increased stroke volume; not necessarily disease. Anxiety, hyperthyroidism, severe anemia. Normal location, under 2/3 of systole.","s":3},{"t":"Sustained (pressure load)","d":"Hypertrophy, increased afterload. Left: aortic stenosis, hypertension. Right: pulmonic stenosis, pulmonary hypertension.","s":3},{"t":"Diffuse (volume load)","d":"Dilation, increased preload. Left: displaced left and down; aortic or mitral regurgitation, cardiomyopathy. Right: atrial septal defect.","s":3},{"t":"Why the areas are where they are","d":"Not over the valves: the next place DOWNSTREAM along the blood flow with no bone in the way. Aortic stenosis can radiate to both carotids.","s":4},{"t":"The five areas","d":"Aortic (right 2nd space), pulmonic (left 2nd), Erb's point (between pulmonic and mitral), tricuspid (lower left sternal border), mitral (apex).","s":4},{"t":"Bell","d":"Low pitch. Light pressure, no gaps. Apex, then medially along the lower sternal border. S3, S4, mitral stenosis.","s":4},{"t":"Diaphragm","d":"High pitch. Press firmly, whole precordium. S1, S2, clicks, opening snap, aortic and mitral regurgitation, friction rubs.","s":4},{"t":"Technique","d":"Quiet room, skin contact always (never over clothing), isolate each sound, close your eyes. Unsure if systolic? Palpate the carotid while listening.","s":4},{"t":"Murmur / thrill / bruit","d":"Murmur: turbulent flow over a valve, heard. Thrill: its vibration, felt with the balls of the hand held still. Bruit: turbulent flow in a vessel, often from narrowing.","s":5},{"t":"Causes of a murmur","d":"Partially obstructed valve; increased flow through a normal valve (child); ejection into a dilated chamber; regurgitation; shunting to a lower pressure chamber.","s":5},{"t":"Seven characteristics","d":"Timing, shape, location, radiation, intensity, pitch, quality.","s":5},{"t":"Shapes","d":"Crescendo-decrescendo (diamond); decrescendo (starts maximal, fades); plateau (unchanging); crescendo (grows).","s":5},{"t":"Levine grades","d":"1 heard only after tuning in. 2 heard immediately. 3 moderately loud. 4 loud WITH THRILL. 5 thrill, heard with stethoscope partly off. 6 thrill, heard entirely off.","s":5},{"t":"Pitch and quality","d":"High, medium, low. Blowing, harsh, rumbling, musical.","s":5},{"t":"Innocent","d":"No structural abnormality; grade 1-3; softer on standing, sitting up or Valsalva; most common in childhood, but healthy adults can have them. Defined by no symptoms or structural disease, not by grade. A thrill = not innocent.","s":5},{"t":"Physiologic vs pathologic","d":"Physiologic: anemia, pregnancy, fever, hyperthyroidism. Pathologic: structural (aortic or pulmonic stenosis, hypertrophic cardiomyopathy, atrial septal defect).","s":5},{"t":"Aortic stenosis","d":"Midsystolic, crescendo-decrescendo</td><td>Medium, harsh</td><td>Aortic area</td><td>Carotids, down left sternal border, even apex</td><td>Sitting forward; louder with squatting and leg raise","s":6},{"t":"Pulmonic stenosis","d":"Midsystolic, crescendo-decrescendo</td><td>Medium, harsh</td><td>Pulmonic area</td><td>Left shoulder and neck if loud</td><td>None","s":6},{"t":"Hypertrophic cardiomyopathy","d":"Midsystolic, crescendo-decrescendo</td><td>Medium, harsh</td><td>Erb's point, tricuspid area</td><td>Down left sternal border to apex; usually not the neck</td><td>Softer with squatting; LOUDER with Valsalva and standing","s":6},{"t":"Tricuspid regurgitation","d":"Pansystolic, plateau</td><td>Medium, blowing</td><td>Lower left sternal border</td><td>Right sternum, xiphoid; NOT the axilla</td><td>May increase slightly with inspiration","s":6},{"t":"Mitral regurgitation","d":"Pansystolic, holosystolic</td><td>Medium-high, harsh</td><td>Apex</td><td>LEFT AXILLA</td><td>Louder with handgrip or squatting; apical thrill if loud","s":6},{"t":"Aortic regurgitation","d":"Early diastolic, decrescendo; grade 1-3</td><td>High, blowing (like breath sounds)</td><td>Aortic area, down left spaces</td><td>Apex if loud</td><td>Sit forward, exhale, hold","s":6},{"t":"Pulmonic regurgitation","d":"Early diastolic, decrescendo; grade 1-3</td><td>High</td><td>Pulmonic area</td><td>None</td><td>None; may increase with inspiration","s":6},{"t":"Mitral stenosis","d":"Mid to late diastolic, decrescendo; grade 1-4</td><td>Low rumble: BELL</td><td>Apex</td><td>Little or none</td><td>Bell at the apical impulse, left lateral decubitus","s":6},{"t":"Tricuspid stenosis","d":"Mid to late diastolic, decrescendo; grade 1-4</td><td>Low rumble after an opening snap: bell</td><td>Lower left sternal border near xiphoid</td><td>Little or none</td><td>Bell","s":6},{"t":"Pericardial friction rub","d":"Scratchy, both systole and diastole; plateau</td><td>High: diaphragm</td><td>Erb's point</td><td>Little</td><td>Louder leaning forward, exhaled, breath held","s":6},{"t":"Valsalva (strain)","d":"Forceful expiration against a closed airway: bear down, or push against your hand on the mid-abdomen. Less preload. Hypertrophic cardiomyopathy LOUDER; aortic stenosis softer or unchanged.","s":7},{"t":"Standing from squatting","d":"Less venous return, less preload. Hypertrophic cardiomyopathy LOUDER; aortic stenosis SOFTER; mitral prolapse click earlier, murmur longer.","s":7},{"t":"Squatting from standing or leg raise","d":"More venous return, more preload. Hypertrophic cardiomyopathy SOFTER; aortic stenosis LOUDER; mitral prolapse click later, murmur shorter.","s":7},{"t":"Isometric handgrip","d":"Raises resistance. Increases mitral regurgitation, ventricular septal defect, aortic regurgitation, mitral stenosis (pulmonic stenosis is not expected to increase).","s":7},{"t":"The one rule","d":"Smaller left ventricle = more outflow obstruction in hypertrophic cardiomyopathy. More blood through a fixed narrow valve = louder aortic stenosis.","s":7},{"t":"Positions","d":"Left lateral decubitus: apex (S3, S4, mitral stenosis). Seated, leaning forward, exhaled: aortic regurgitation, friction rub.","s":7},{"t":"Inspection","d":"Size, symmetry, venous pattern, hair growth, edema, skin color, ulcers. Always compare sides.","s":8},{"t":"Capillary refill","d":"2-3 seconds. Quincke's sign: nail bed flashes red to pale with each beat.","s":8},{"t":"Pulse grades","d":"4+ bounding, 3+ increased, 2+ brisk normal, 1+ faint, 0 absent. ALWAYS compare both sides.","s":8},{"t":"Arterial insufficiency","d":"Claudication (pain with walking), can progress to rest pain; pale or dusky red; cool; NO edema; thin shiny skin, hair loss; painful toe ulcer; gangrene; decreased pulses; pallor on elevation, dependent rubor.","s":8},{"t":"Venous insufficiency","d":"Pain usually none or mild (ache, eases with elevation); brown hemosiderin staining; normal temperature; pitting edema; thickened skin; ulcer at the medial and lateral malleolus; gangrene rare; NORMAL pulses.","s":8},{"t":"Pulse landmarks","d":"Brachial: medial to biceps tendon. Radial: lateral wrist. Ulnar: medial wrist, may be impalpable. Femoral: below inguinal ligament, midway anterior superior iliac spine to pubic symphysis. Dorsalis pedis: lateral to great toe extensor tendon. Posterior tibial: behind medial malleolus.","s":8},{"t":"Carotid","d":"Hold breath, auscultate BEFORE palpating, one side at a time.","s":8},{"t":"Pulse lag","d":"Radial and femoral together; femoral lag = coarctation of the aorta.","s":8},{"t":"Bruit sites","d":"Aorta (upper midline); renal 3-4 cm lateral to aorta; iliac 3-4 cm lateral to umbilicus, about 2 cm below; femoral.","s":8},{"t":"Allen test","d":"Compress radial and ulnar, clench 30 s, open; release ULNAR and watch the hand pink up; repeat for radial. Persistent pallor = occlusion. Done before an arterial blood gas.","s":8},{"t":"Ankle brachial index","d":"Higher ankle pressure (dorsalis pedis or posterior tibial) over brachial systolic, each leg, 2 decimals. Supine 10 min; inflate 20 mm Hg above last pulse; deflate 1 mm Hg per second.","s":8},{"t":"Index values","d":"Over 1.40 noncompressible calcified vessel. 0.90-1.40 normal. Under 0.90 peripheral arterial disease. Under 0.50 severe.","s":8},{"t":"Homans sign","d":"Knee bent, dorsiflex the foot quickly; pain BEHIND THE KNEE = positive, classically. Deep vein thrombosis. Now considered unreliable: never decide on it alone.","s":8},{"t":"Definition","d":"Excess fluid in the extravascular interstitial space. Up to 10% of body weight before pitting. Obscures veins, tendons, bony prominences.","s":9},{"t":"Technique","d":"Thumb pressed firmly at least 2 seconds over the dorsum of the foot, behind the medial malleolus, or the shins. Describe depth AND extent. Unilateral or bilateral?","s":9},{"t":"1+","d":"2 mm, disappears rapidly.","s":9},{"t":"2+","d":"4 mm, gone in 10-15 seconds.","s":9},{"t":"3+","d":"6 mm, may last more than 1 minute.","s":9},{"t":"4+","d":"8 mm, can last more than 2 minutes.","s":9},{"t":"Order","d":"Inspection (including jugular venous pressure), palpation, auscultation, special techniques.","s":10},{"t":"Equipment and room","d":"Stethoscope, ruler, penlight, tongue depressor. Tangential light, quiet room, warm hands, short nails.","s":10},{"t":"The patient","d":"In a gown; never examine over clothing. Positioning: 30-45 degrees, left lateral decubitus, seated leaning forward.","s":10},{"t":"Cardiac OSCE (objective structured clinical examination)","d":"21 October. The whole station is on the Cardiac OSCE run-sheet.","s":10},{"t":"★ Copious foul sputum","d":"Cystic fibrosis or bronchiectasis. The one line she tied to an exam question, her own board exam ('I've had that as a board question'). Foul-smelling alone = anaerobic lung abscess.","s":11},{"t":"★ Which way the trachea goes","d":"Atelectasis PULLS it to the same side (shrinkage). Tension pneumothorax and a large effusion PUSH it to the unaffected side. Pneumonia: midline.","s":11},{"t":"★ Silent chest","d":"In asthma, wheezing fades as airways narrow further; minimal air movement. Needs immediate intervention. Quiet is not better.","s":11},{"t":"★ Stridor is an emergency","d":"High-pitched, inspiratory, over the neck = upper airway obstruction (larynx, trachea). Immediate intervention.","s":11},{"t":"★ Pleural vs pericardial rub","d":"Ask for a breath hold: the pleural rub disappears, the pericardial friction rub keeps going with the heart.","s":11},{"t":"★ Aspiration goes right","d":"Right main bronchus is wider, shorter, more vertical. Said twice, with two cases.","s":11},{"t":"★ Location makes the breath sound","d":"Bronchial sounds out at the bases or periphery = consolidation (pneumonia). Same logic as increased fremitus.","s":11},{"t":"★ Onset narrows the differential","d":"Sudden vs gradual first. Dyspnea at rest is more worrying. Hyperventilation: anxiety is the last thing you call it.","s":11},{"t":"Time on topic","d":"Nothing named as on or off this exam in 90 minutes. About half the time went to the examination itself, the sounds most of all. Patient setup and prep skipped ('you've done the lung exam').","s":11},{"t":"Counting","d":"Sternal angle (angle of Louis) = 2nd rib, lines up with T4. Each space takes the number of the rib above. Scapular tip = about 7th rib.","s":12},{"t":"2nd intercostal space","d":"Needle decompression of a tension pneumothorax (anterior).","s":12},{"t":"Between 4th and 5th ribs","d":"Chest tube. Triangle of safety, midaxillary line: pectoralis major (front), latissimus dorsi (back), nipple line, 4th or 5th space (below).","s":12},{"t":"T7-T8, posterior","d":"Thoracentesis: 7th intercostal space, needle just ABOVE the 8th rib.","s":12},{"t":"Always above a rib","d":"Neurovascular structures run along each rib's INFERIOR margin.","s":12},{"t":"T4","d":"Lower margin of the endotracheal tube on a chest x-ray.","s":12},{"t":"Lung borders","d":"Apices 2-4 cm above the medial third of the clavicle. Inferior: 6th rib midclavicular, 8th rib midaxillary, T10 posterior.","s":12},{"t":"Lobes and fissures","d":"Right: upper, middle, lower. Left: upper and lower only. Oblique: T3 behind to 6th rib in front. Right horizontal: follows the 4th rib to the 5th at the midaxillary line.","s":12},{"t":"Airways","d":"Carina at the sternal angle / T4-T5. Right main bronchus wider, shorter, more vertical; left longer, horizontal, under the aortic arch. Alveoli = gas exchange.","s":12},{"t":"Pleurae","d":"Visceral: no sensory nerves. Parietal: intercostal and phrenic nerves, so pleuritic pain on deep inspiration. Pleural fluid surface tension holds lung to chest wall.","s":12},{"t":"Effusion types","d":"Transudative: heart failure, cirrhosis, nephrotic syndrome. Exudative: pneumonia, malignancy, pulmonary embolism, tuberculosis, pancreatitis.","s":12},{"t":"Open","d":"Open-ended question first; the patient's own words. Then onset, timing, triggers, position, exposures, impact on daily life.","s":13},{"t":"Exposures","d":"Tobacco and nicotine; marijuana (smoked, vaped, ingested); recreational drugs incl. inhaled or intranasal; occupation and environment; recent travel.","s":13},{"t":"Chest pain patterns","d":"Pressure = angina or infarction. Sudden tearing to the back = aortic dissection. Sharp pleuritic (inspiration, cough) = pulmonary embolism, pneumothorax, pneumonia, pleuritis. Sharp positional, better sitting forward = pericarditis. Burning postprandial = reflux. Reproducible = chest wall, costochondritis.","s":13},{"t":"Dyspnea","d":"Painless but uncomfortable awareness of breathing, inappropriate to exertion. Severity: distance, flights of stairs, groceries, making the bed, change from baseline.","s":13},{"t":"Wheezing","d":"Musical, audible to the patient and others. Partial LOWER airway obstruction: asthma secretions and inflammation, or a foreign body.","s":13},{"t":"Cough","d":"Reflex from receptors in the larynx, trachea, large bronchi. Acute under 3 weeks; subacute 3-8; chronic over 8. Slide 19's second line was corrected aloud to 'related to medication'.","s":13},{"t":"Sputum","d":"Mucoid (translucent, white, gray) = viral, postnasal drip. Purulent (yellow, green) = bacterial pneumonia. Foul = anaerobic lung abscess. Copious foul = cystic fibrosis, bronchiectasis.","s":13},{"t":"Sleep","d":"Loud persistent snoring = hallmark of obstructive sleep apnea. Witnessed apneas (10 seconds or more), choking on waking, morning headache, daytime sleepiness. Others: restless legs, narcolepsy, insomnia.","s":13},{"t":"Hemoptysis","d":"Blood coughed up from the LOWER respiratory tract, streaks to frank blood. Rare in infants, children, adolescents. Confirm the source before using the word.","s":14},{"t":"Stomach or lung?","d":"Vomited = likely gastrointestinal. Stomach blood is darker, with food particles. Nasopharyngeal or gastric blood can be aspirated and coughed out.","s":14},{"t":"Massive","d":"More than 600 mL in 24 hours: life threatening, urgent intervention (and a patient pouring blood is an emergency before you reach 600).","s":14},{"t":"Causes","d":"Bacterial pneumonias, chronic bronchitis, bronchiectasis, pulmonary tuberculosis, lung abscess, lung cancer, pulmonary embolism.","s":14},{"t":"Clubbing","d":"Bulbous swelling at the nail base; loss of the nail-to-proximal-fold angle; nail bed spongy or floating.","s":14},{"t":"Clubbing seen in","d":"Interstitial lung disease, pulmonary fibrosis, lung cancer, bronchiectasis, cystic fibrosis, lung abscess; congenital heart disease, inflammatory bowel disease, malignancy.","s":14},{"t":"SUDDEN: pneumothorax","d":"Abrupt unilateral pleuritic pain, cough. Trauma, recent procedure, emphysema, prior pneumothorax.","s":15},{"t":"SUDDEN: pulmonary embolism","d":"Unexplained dyspnea; pleuritic pain, hemoptysis, syncope, one-sided leg symptoms. Prior clot, surgery, immobility, cancer, estrogen, pregnancy or postpartum.","s":15},{"t":"ACUTE: pneumonia","d":"Fever, chills, cough, sputum, pleuritic pain. Recent illness, aspiration risk, immunosuppression.","s":15},{"t":"Left-sided heart failure","d":"Gradual or sudden; worse on exertion or lying flat. Orthopnea, paroxysmal nocturnal dyspnea, cough, edema, weight gain. Hypertension, prior infarction.","s":15},{"t":"GRADUAL: chronic bronchitis","d":"Chronic PRODUCTIVE cough, then progressive dyspnea; recurrent infections, wheeze. Smoking, air pollutants.","s":15},{"t":"GRADUAL: obstructive disease","d":"Slowly progressive exertional dyspnea, cough later, scant sputum. Smoking, inhalational exposures, alpha-1 antitrypsin deficiency.","s":15},{"t":"GRADUAL: interstitial lung disease","d":"Gradually progressive exertional dyspnea, DRY cough, fatigue, weakness. Autoimmune disease, medications, occupation.","s":15},{"t":"EPISODIC: asthma","d":"Symptom-free intervals, often worse at night; wheeze, cough, tightness. Allergens, infections, exercise, cold air, irritants.","s":15},{"t":"EPISODIC: hyperventilation","d":"At rest or with distress; air hunger, sighing, lightheadedness, perioral or extremity tingling. Medical causes first; anxiety last.","s":15},{"t":"Order and position","d":"Inspection, palpation, percussion, auscultation. Back: sitting, arms folded; too weak to sit = roll to one side, then the other.","s":16},{"t":"Survey","d":"Rate, rhythm, depth, effort; is expiration prolonged? Normal rate is given two ways (12-18 on slide 31, about 14-20 on slide 32); not tested.","s":16},{"t":"Patterns","d":"Tachypnea = rapid shallow. Hyperpnea = rapid deep. Cheyne-Stokes = deep breathing alternating with apnea. Ataxic (Biot) = irregular, deep breaths that stop suddenly. Obstructive = prolonged expiration.","s":16},{"t":"Color","d":"Central cyanosis (lips, tongue, mucosa) = hypoxia. Pallor and diaphoresis = heart failure, acute coronary syndrome.","s":16},{"t":"Neck","d":"Inspiration: sternocleidomastoid and scalene. Expiration: intercostals and abdominal obliques. Trachea midline?","s":16},{"t":"Chest size","d":"Anteroposterior to lateral ratio 0.7-0.9, rising with age; over 0.9 in obstructive disease = barrel chest.","s":16},{"t":"Movement","d":"Asymmetric expansion = large effusion. Inspiratory retraction = severe asthma, obstructive disease, upper airway obstruction. One-sided lag = pleural disease or phrenic nerve injury.","s":16},{"t":"Deformities","d":"Pigeon (carinatum): sternum forward. Funnel (excavatum): lower sternum sunk, may cause murmurs. Flail: rib fractures, segment caves IN on inspiration. Kyphoscoliosis: findings hard to interpret.","s":16},{"t":"Palpation","d":"Crepitus = air in subcutaneous tissue (with chest wall edema: mediastinitis). Tenderness, bruising, step-off = rib fracture. Sinus tracts = pleural or lung infection.","s":16},{"t":"Expansion","d":"One-sided decrease or delay: fibrosis, effusion, lobar pneumonia, splinting, bronchial obstruction, hemidiaphragm paralysis.","s":16},{"t":"Fremitus","d":"UP = unilateral pneumonia (consolidation). DOWN = thick wall, obstructed bronchus, obstructive disease, effusion, fibrosis, pneumothorax, tumor.","s":16},{"t":"Percussion","d":"Resonant = healthy. Dull = fluid or solid replacing air. Generalized hyperresonance = obstructive disease or asthma. One-sided hyperresonance = large pneumothorax or bulla. Cannot reach deep lesions.","s":17},{"t":"Diaphragmatic excursion","d":"Dullness marked at full expiration and full inspiration. HIGH level = effusion, or raised hemidiaphragm (atelectasis, phrenic nerve). Normal range given as 3-5.5 cm and 3-5 cm.","s":17},{"t":"Before listening","d":"Cough once or twice; patient de-robed (gowns and chest hair make sounds).","s":17},{"t":"Vesicular","d":"Inspiration longer; soft, low. Most of both lungs.","s":17},{"t":"Bronchovesicular","d":"About equal; intermediate. 1st and 2nd interspaces in front, between the scapulae.","s":17},{"t":"Bronchial","d":"Expiration longer; loud, high. Over the manubrium. A silent gap between phases suggests bronchial.","s":17},{"t":"Tracheal","d":"About equal; very loud, high. Over the trachea in the neck.","s":17},{"t":"In the wrong place","d":"Bronchial or bronchovesicular where vesicular belongs = air replaced by fluid or consolidation.","s":17},{"t":"Crackles (rales)","d":"Non-musical, discontinuous; deflated small airways snapping open on inspiration.","s":18},{"t":"Fine crackles","d":"Soft, high, brief; mid-to-late inspiration, dependent lung; CHANGE with position. Pulmonary fibrosis, interstitial fibrosis, interstitial pneumonitis.","s":18},{"t":"Coarse crackles","d":"Loud, low, popping; early inspiration through expiration; do NOT change with position. Obstructive disease, asthma, bronchiectasis, pneumonia, heart failure.","s":18},{"t":"Wheezes","d":"Continuous, musical; rapid airflow through bronchi narrowed almost shut. Typical of asthma. Localized = foreign body, mucous plug, tumor.","s":18},{"t":"Rhonchi","d":"Variant of wheezes, LOWER pitch; may clear with coughing (secretions).","s":18},{"t":"Stridor","d":"Continuous, high-pitched; upper airway narrowing; over the neck on inspiration. Intubation stenosis, edema after device removal, epiglottitis, foreign body, anaphylaxis.","s":18},{"t":"Pleural rub","d":"Grating, creaking, biphasic; axilla and lower bases; not changed by coughing; louder with firm pressure; gone with a breath hold.","s":18},{"t":"Mediastinal crunch (Hamman sign)","d":"Precordial crackles in time with the HEARTBEAT; air in the mediastinum; left lateral decubitus. Trauma, drugs, childbirth, rapid scuba ascent.","s":18},{"t":"Asthma","d":"Tachypnea, retractions. Diminished fremitus. Resonant to diffusely hyperresonant. Wheezes, prolonged expiration.","s":19},{"t":"Atelectasis","d":"Narrowed spaces, trachea TOWARD the side. Diminished fremitus (may rise in right upper lobe). Dull. Sounds absent while the plug persists; crackles. Commonest respiratory problem after surgery.","s":19},{"t":"Pneumonia","d":"Trachea midline. INCREASED fremitus. Dull over the airless area. Bronchial sounds, late inspiratory crackles, egophony, bronchophony, whispered pectoriloquy.","s":19},{"t":"Pneumothorax","d":"Trachea to the unaffected side only if tension. Decreased or absent fremitus. Hyperresonant or tympanic. Decreased or absent sounds; possible rub.","s":19},{"t":"Pleural effusion","d":"Large: asymmetric expansion, trachea to unaffected side. Fremitus down (up toward the top). Dull, high diaphragm. Sounds down; bronchial near the top; possible rub.","s":19},{"t":"Egophony","d":"Say 'ee'. Normal: muffled long E. Positive: 'ee' heard as 'a'.","s":19},{"t":"Bronchophony","d":"Say 'ninety-nine'. Normal: muffled. Positive: louder.","s":19},{"t":"Whispered pectoriloquy","d":"Whisper 'ninety-nine'. Normal: faint, indistinct. Positive: louder, clearer.","s":19},{"t":"Pneumonia odds","d":"Fever and cough plus bronchial breath sounds and egophony: more than triples the likelihood of pneumonia.","s":19},{"t":"Pulmonary OSCE (objective structured clinical examination)","d":"10 November. The whole station is on the Pulmonary OSCE run-sheet.","s":19}],"map":{"physical-diagnosis-2-exam-2-cardiovascular-exam-quiz-version-2":[74,23,82,-1,47,12,72,24,39,10,58,66,68,-1,22,69,35,24,56,67,-1,15,55,63,17,55,32,48,5,-1],"physical-diagnosis-2-exam-2-cardiovascular-exam-quiz":[30,54,70,36,-1,13,-1,26,71,44,31,-1,10,-1,66,-1,68,76,45,37,72,71,26,57,53,24,65,51,39,45],"physical-diagnosis-2-exam-2-heart-sound-quiz":[-1,25,24,23,20,21,-1,23,50,23,23,24,53,47,46,51,20,21],"physical-diagnosis-2-exam-2-thorax-lung-exam-quiz-version-2":[90,149,138,118,131,127,139,96,128,111,85,108,125,133,132,122,154,117,133,88,139,156,159,158,147,155,109,96,123,110],"physical-diagnosis-2-exam-2-thorax-lung-exam-quiz":[117,155,117,151,135,107,107,97,87,159,106,121,120,154,153,103,119,157,160,144,156,158,162,135,85,110,114,126,98,-1]}};
